<template>
    <div class="total-price">
      <div class="btn-box" :class="{'active': showPriceMask}">
        <div class="left" @click="openMask">
          <span class="desc">总价</span>
          <span class="red">¥</span>
          <span class="red price">{{priceInfo.total_price}}</span>
          <i class="icon iconfont">&#xe62b;</i>
        </div>
        <div class="right">
          <button class="btn" @click="saveOrder">提交订单</button>
        </div>
      </div>

      <div class="mask price-mask" :class="{'active': showPriceMask}" @click="openMask">
        <div class="mask-content" @click.stop="preventClick">
          <div class="title-box">
            <span class="title">费用明细</span>
          </div>
          <div class="list">
            <div class="line">
              <span>基础配送费</span>
              <span>¥{{priceInfo.basic_distance_price}}</span>
            </div>
            <div class="line" v-show="priceInfo.extra_distance_price > 0">
              <span>超出距离费用</span>
              <span>¥{{priceInfo.extra_distance_price}}</span>
            </div>
            <div class="line" v-show="priceInfo.basic_weight_price > 0">
              <span>基础重量费</span>
              <span>¥{{priceInfo.basic_weight_price}}</span>
            </div>
            <div class="line" v-show="priceInfo.extra_weight_price > 0">
              <span>超出重量费用</span>
              <span>¥{{priceInfo.extra_weight_price}}</span>
            </div>
            <div class="line" v-show="priceInfo.tip_price > 0">
              <span>小费</span>
              <span>¥{{priceInfo.tip_price}}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
</template>

<script>
export default {
  name: 'TotalPrice',
  data () {
    return {
      showPriceMask: false
    }
  },
  props: ['priceInfo'],
  methods: {
    openMask () {
      this.showPriceMask = !this.showPriceMask
    },
    preventClick () {
      return false
    },
    saveOrder () {
      this.$emit('saveOrder')
    }
  }
}
</script>

