<template>
    <div class="send-confirm-wrapper">
      <OrderMap :start=" confirmType == 'send' ? sendStart : buyStart " :end=" confirmType == 'send' ? sendEnd : (buyEnd ? buyEnd : buyEndDefault) " :type="confirmType"/>
      <div class="contents">
        <div v-if="confirmType == 'send'">
          <SelectGoods class="border-b" :showTxt="sendGoods.showTxt" />
          <ImgUploader class="mb10" :quality="quality" @getImgFile="getImgFile"/>
          <AddressInput addressDesc="从哪里发出" type="sendStart" :addressInfo="sendStart">
            <div class="address-from send" slot="address-from">发</div>
          </AddressInput>
          <AddressInput class="recieve mb10" addressDesc="送到哪里去" type="sendEnd" :addressInfo="sendEnd">
            <div class="address-from receive" slot="address-from">送</div>
          </AddressInput>

          <div class="notes-box">
            <span>备注：</span>
            <input class="notes-input" type="text" placeholder="物品描述或送件要求" v-model="sendRemark">
            <i class="icon iconfont" v-show="sendRemark" @click="clearRemark">&#xe80b;</i>
          </div>
          <OrderTip class="border-b" :tip="tip" @getTip="getTip"/>
          <SelectTime class="mb10" v-if="timeInfo.length > 0" :timeInfo="timeInfo" :type="confirmType" @getTime="getTime"/>
        </div>

        <div v-else>
          <div class="text-box">
            <div class="desc-wrapper">
              <textarea class="buy-desc" placeholder="我想买..." maxlength="100" v-model="buyGoodsDesc" @input="buyGoodsInput"></textarea>
            </div>
          </div>
          <div class="mb10 buy-weight-box" v-if="showBuyWeight">
            <div class="buy-weight" @click="selectBuyWeight">
              <span class="left">商品重量</span>
              <div class="right">
                <span v-if="!buyGoodsWeight.showTxt">请选择</span>
                <span class="desc" v-else>{{buyGoodsWeight.showTxt}}</span>
                <i class="icon iconfont">&#xe62b;</i>
              </div>
            </div>
          </div>
          <div class="predicted-box">
            <div class="predicted-cost" @click="openCostMask">
              <span class="left"><i class="icon iconfont">&#xe60c;</i>骑手垫付商品费</span>
              <span class="right">{{estimatedCost ? '¥' + estimatedCost : '预估商品费'}}<i class="icon iconfont">&#xe62b;</i></span>
            </div>
            <div class="mask" :class="{'active': showCostMask}" @click="openCostMask">
              <div class="mask-content cost-mask" @click.stop="preventDefault">
                <div class="title-box">
                  <span @click="openCostMask">取消</span>
                  <span class="title">预估商品费</span>
                  <span @click="openCostMask('confirm')">确认</span>
                </div>
                <div class="desc">供骑手代购时参考（可选填）</div>
                <div class="input-box">
                  <span>预估</span><span class="icon">¥</span>
                  <span class="width-tag" ref="costWidth">{{estimatedCostInput}}</span>
                  <input class="input" type="text" maxlength="8" ref="costInput" :style="estimatedCostStyle" v-model="estimatedCostInput" @input="inputCost">
                </div>
              </div>
            </div>
          </div>
          <ImgUploader class="mb10" :quality="quality" @getImgFile="getImgFile"/>

          <div class="mb10 buy-select-address">
            <div class="select-address">
              <div>购买</div>
              <div class="item" :class="{'active': selectBuyAddress}" @click="selectBuyType(true)">指定地址<span class="desc">更精准</span></div>
              <div class="item" :class="{'active': !selectBuyAddress}" @click="selectBuyType(false)">骑手就近购买</div>
            </div>
            <AddressInput addressDesc="选择购买地址" v-show="selectBuyAddress" type="buyStart" :addressInfo="buyStart">
              <div class="address-from send" slot="address-from"></div>
            </AddressInput>
            <div class="border-box"><div class="border"></div></div>
            <AddressInput class="recieve mb10" addressDesc="送到哪里去" type="buyEnd" :addressInfo="buyEnd">
              <div class="address-from receive" slot="address-from">收货</div>
            </AddressInput>
          </div>

          <OrderTip class="border-b" :tip="tip" @getTip="getTip"/>
          <SelectTime class="mb10" v-if="timeInfo.length > 0" :timeInfo="timeInfo" :type="confirmType" @getTime="getTime"/>
        </div>

      </div>

      <TotalPrice :priceInfo="priceInfo" @saveOrder="getOrderId" />

    </div>
</template>

<script>
import OrderMap from '../../components/OrderMap/OrderMap'
import SelectGoods from '../../components/SelectGoods/SelectGoods'
import AddressInput from '../../components/AddressInput/AddressInput'
import OrderTip from '../../components/OrderTip/OrderTip'
import TotalPrice from '../../components/TotalPrice/TotalPrice'
import SelectTime from '../../components/SelectTime/SelectTime'
import ImgUploader from '../../components/ImgUploader/ImgUploader'

export default {
  name: 'SendConfirm',
  data () {
    return {
      confirmType: 'send', // 当前订单类型
      showCostMask: false, // 是否显示预估商品费用弹窗
      selectBuyAddress: true, // 帮我买 是否选择了指定地址购买
      sendStart: '',
      sendEnd: '',
      sendGoods: '',
      sendRemark: '', // 帮我送 备注
      buyStart: '',
      buyEnd: '',
      tip: 0, // 小费
      publishDetail: '', // 一些公共信息：取件时间列表、计算规则等
      timeInfo: [],
      time: '', // 选择的时间值
      buyEndDefault: {},
      cid: '',
      showBuyWeight: true, // 是否显示帮我买商品重量
      buyGoodsDesc: '', // 帮我买商品描述
      buyGoodsWeight: {
        weight: 0
      }, // 帮我买商品重量
      priceInfo: { total_price: 0 }, // 价格信息
      estimatedCost: '', // 帮我买 预估商品费用
      estimatedCostStyle: '',
      estimatedCostInput: '',
      files: [],
      quality: 0.5 // 图片压缩质量 0~1之间的数
    }
  },
  created () {
    this.confirmType = this.$globalData.confirmType
    this.tip = this.$globalData.tip
    if (this.confirmType == 'send') {
      this.$globalData.confirmBack = true
      this.sendStart = this.$globalData.sendStart
      this.sendEnd = this.$globalData.sendEnd
      this.sendGoods = this.$globalData.sendGoods
      this.cid = this.$globalData.config.catList[0].cid
    } else {
      this.buyEndDefault = this.$globalData.currentPosition
      this.buyStart = this.$globalData.buyStart
      this.buyEnd = this.$globalData.buyEnd
      this.buyGoodsDesc = this.$globalData.buyGoodsDesc
      this.buyGoodsWeight = this.$globalData.buyGoodsWeight
      this.selectBuyAddress = this.$globalData.selectBuyAddress
      this.estimatedCost = this.$globalData.estimatedCost
      this.cid = this.$globalData.config.catList[1].cid
    }
    this.getPublishDetail()
  },
  methods: {
    preventDefault () {
      return false
    },
    // 获取图片信息
    getImgFile (files) {
      this.$globalData.imgFiles = this.files = files
    },
    // 帮我买打开预估费用弹窗
    openCostMask (type) {
      if (type == 'confirm') {
        this.$globalData.estimatedCost = this.estimatedCost = this.estimatedCostInput
      }
      this.showCostMask = !this.showCostMask
      if (this.showCostMask) {
        this.$refs.costInput.focus()
        this.estimatedCostInput = this.estimatedCost
        this.$nextTick(function () {
          this.estimatedCostStyle = this.estimatedCostInput ? `width:${this.$refs.costWidth.clientWidth}px` : `width:2px`
        })
      }
    },
    // 帮我买 输入商品费用
    inputCost () {
      this.$nextTick(function () {
        this.estimatedCostStyle = this.estimatedCostInput ? `width:${this.$refs.costWidth.clientWidth}px` : `width:2px`
      })
    },
    selectBuyWeight () {
      this.$router.push('/goodstype')
    },
    // 帮我买 是否指定地址购买
    selectBuyType (type) {
      if (type == this.selectBuyAddress) {
        return
      }
      this.$globalData.selectBuyAddress = this.selectBuyAddress = type
      if (!type) {
        this.buyStart = ''
      } else {
        this.buyStart = this.$globalData.buyStart
      }
    },
    // 帮我送 清除备注输入框
    clearRemark () {
      this.sendRemark = ''
    },
    // 获取小费的值
    getTip (tip) {
      console.log('44444444444', tip)
      this.$globalData.tip = this.tip = tip
      this.getPrice()
    },
    getTime (time) {
      this.$globalData.time = this.time = time
      this.getPrice()
    },
    async getPublishDetail () {
      try {
        let res = await this.$api.getPublishDetail({ cid: this.cid })
        console.log('res', res)
        if (res.errorMsg) {
          return
        }
        this.timeInfo = res.daysList
        this.showBuyWeight = res.config.service_weight_multilevel_switch == 1
        this.publishDetail = res
      } catch (e) {
        console.log('获取publish_detail失败 getPublishDetail', e)
      }
    },
    buyGoodsInput () {
      if (this.buyGoodsDesc.length >= 100) {
        this.$toast('最多只能输入100个字')
      }
      this.$globalData.buyGoodsDesc = this.buyGoodsDesc
    },
    async getPrice () {
      try {
        let priceParam = {
          cid: this.cid,
          buy_type: this.selectBuyAddress ? 2 : 1,
          time_info: this.time,
          tip_price: this.tip,
          weight: this.confirmType == 'send' ? this.sendGoods.weight : this.buyGoodsWeight.weight
        }
        if (this[this.confirmType + 'Start']) {
          priceParam.start_adress_lng = this[this.confirmType + 'Start'].point.lng
          priceParam.start_adress_lat = this[this.confirmType + 'Start'].point.lat
        }
        if (this[this.confirmType + 'End']) {
          priceParam.end_adress_lng = this[this.confirmType + 'End'].point.lng
          priceParam.end_adress_lat = this[this.confirmType + 'End'].point.lat
        }
        let res = await this.$api.getPrice(priceParam)
        console.log('计算价格结果', res)
        if (res.errorMsg) {
          return
        }
        this.priceInfo = res
      } catch (e) {
        console.log('计算价格错误 getPrice', e)
      }
    },
    // 提交订单
    async getOrderId () {
      try {
        let type = this.confirmType
        let formData = new FormData()
        formData.append('cid', this.cid)
        formData.append('time_info', this.time)
        formData.append('tip_price', this.tip)
        if (type == 'send') {
          formData.append('weight', this.sendGoods.weight)
          formData.append('remarks', this.sendRemark)
          formData.append('goods_catgory', this.sendGoods.type)
        } else {
          formData.append('weight', this.buyGoodsWeight.weight)
          let buyType = this.selectBuyAddress ? 2 : 1
          formData.append('buy_type', buyType)
          formData.append('estimate_goods_price', this.estimatedCost)
          formData.append('goods_remarks', this.buyGoodsDesc)
        }
        if (this[type + 'Start']) {
          formData.append('start_adress_lng', this[type + 'Start'].point.lng)
          formData.append('start_adress_lat', this[type + 'Start'].point.lat)
          formData.append('start_adress_name', this[type + 'Start'].name)
          formData.append('start_adress_phone', this[type + 'Start'].phone)
          formData.append('start_adress_detail', this[type + 'Start'].detail)
          formData.append('start_adress_area_id', this[type + 'Start'].adress_id)
          formData.append('start_area_id', this[type + 'Start'].area)
          formData.append('start_city_id', this[type + 'Start'].city)
          formData.append('start_province_id', this[type + 'Start'].province)
        }
        if (this[type + 'End']) {
          formData.append('end_adress_lng', this[type + 'End'].point.lng)
          formData.append('end_adress_lat', this[type + 'End'].point.lat)
          formData.append('end_adress_name', this[type + 'End'].name)
          formData.append('end_adress_phone', this[type + 'End'].phone)
          formData.append('end_adress_detail', this[type + 'End'].detail)
        }
        if (this.files.length > 0) {
          for (let i = 0; i < this.files.length; i++) {
            formData.append('imgFile' + i, this.files[i], this.files[i].name)
          }
        }

        let res = ''
        if (type == 'send') {
          res = await this.$api.getSendOrderId(formData)
        } else {
          res = await this.$api.getBuyOrderId(formData)
        }
        if (res.errMsg) {
          this.$toast(res.errMsg)
          return
        } else {
          // this.$toast(res.msg)
          if (this.$util.checkWeixinApp()) {
            this.$wx.miniProgram.navigateTo({
              url: `/pages/pay/index?order_id=${res.order_id}&type=${res.type}`
            })
          } else {
            location.replace(`${process.env.VUE_APP_BASE_API}/wap.php?g=Wap&c=Pay&a=check&type=${res.type}&order_id=${res.order_id}&ticket=${this.$util.storage.get('ticket')}&device_id=${this.$util.storage.get('device')}`)
          }
        }
        console.log('555555555', res)
      } catch (e) {
        console.log('提交订单错误 getOrderId', e)
      }
    }
  },
  components: {
    OrderMap,
    SelectGoods,
    AddressInput,
    OrderTip,
    TotalPrice,
    SelectTime,
    ImgUploader
  }
}
</script>

<style lang="stylus" >
.send-confirm-wrapper
  height 100%
  overflow hidden
  .contents
    padding 0 10px
    height -webkit-calc(100% - 235px)
    height calc(100% - 235px)
    overflow-y auto
    @media only screen and (device-width: 375px) and (device-height: 812px) and (-webkit-device-pixel-ratio: 3)
      height -webkit-calc(100% - 255px)
      height calc(100% - 255px)
    @media only screen and (device-width: 414px) and (device-height: 896px) and (-webkit-device-pixel-ratio:3)
      height -webkit-calc(100% - 255px)
      height calc(100% - 255px)
    @media only screen and (device-width: 414px) and (device-height: 896px) and (-webkit-device-pixel-ratio:2)
      height -webkit-calc(100% - 255px)
      height calc(100% - 255px)
    .border-b
      border-bottom 1PX solid #efefef
    .select-goods
      padding 10px
      color #333
    .address-input
      padding 0 10px
      .address-from
        line-height 16px
        width 16px
        height 16px
        border 1PX solid #6cd184
        color #6cd184
        border-radius 50%
        font-size 12px
        text-align center
        &.receive
          border-color #fc5a50
          color #fc5a50
      &.recieve .detail-box
        border none
    .notes-box
      background #fff
      font-size 14px
      padding 16px 10px
      flexbox()
      align-items center
      border-bottom 1PX solid #efefef
      .notes-input
        flex-grow 1
        margin 0 10px
      .icon
        color #999
        position relative
        &::after
          content ''
          position absolute
          top -10px
          left -10px
          right -10px
          bottom -10px
    .time-box
      background #fff
      flexbox()
      align-items center
      justify-content space-between
      padding 18px 10px
      font-size 14px
    .time-mask
      .picker
        .picker-slot
          font-size 14px
          .picker-item
            opacity .4
            &.picker-selected
              opacity 1
    .title-box
      flexbox()
      justify-content space-between
      align-items center
      font-size 14px
      padding 15px 10px
      border-bottom 1PX solid #e5e5e5
      .title
        font-size 15px
    .text-box
      padding 10px 10px 0 10px
      background #fff
      .desc-wrapper
        padding-bottom 10px
        border-bottom 1PX solid #efefef
        .buy-desc
          width 100%
          resize none
          height 115px
          font-size 14px
          line-height 1.4
    .buy-weight-box
      background #fff
      .buy-weight
        flexbox()
        align-items center
        justify-content space-between
        background #ffffff
        /*border-bottom 1PX solid #efefef*/
        margin 0 10px
        padding 18px 0
        font-size 14px
        .right
          color #999
          .desc
            color #333
          .icon
            vertical-align middle
    .predicted-box
      background #fff
      padding 0 10px
      .predicted-cost
        border-bottom 1PX solid #efefef
        background #fff
        padding 18px 0
        font-size 14px
        flexbox()
        justify-content space-between
        align-items center
        .left
          .icon
            margin-right 5px
        .right
          color #999
      .cost-mask
        font-size 14px
        text-align center
        .desc
          padding 15px 0
        .input-box
          border 1PX solid $color-main
          margin 0 10px 15px
          padding 6px
          color $color-main
          position relative
          .icon
            margin 0 2px 0 5px
          .input
            width 2PX
            text-align center
            color $color-main
          .width-tag
            position absolute
            top -9999px
            left -9999px
    .arrive-time
      background #ffffff
      flexbox()
      justify-content space-between
      font-size 14px
      padding 19.5px 10px
    .buy-select-address
      .select-address
        flexbox()
        align-items center
        background #ffffff
        font-size 14px
        padding 15px 10px
        .item
          margin-left 15px
          border 1PX solid #ddd
          padding 5px
          &.active
            border-color $color-main
            background rgba($color-main, .1)
          .desc
            font-size 12px
            color $color-main
            margin-left 5px
      .address-input
        .address-from
          border none
          font-size 14px
          width 28px
          &.receive
            color #333
            white-space nowrap
        .detail-box
          border none
      .border-box
        padding 0 10px
        background #fff
        .border
          border-bottom 1PX solid #efefef
</style>
